import json
import pandas as pd
TOPICS={'кофе','еда','обслуживание','доставка','цена','атмосфера'}
def parse(answer):
    bad={'sentiment':None,'topic':None,'ok':False}
    if not isinstance(answer,str):
        return bad
    start,end=answer.find('{'),answer.rfind('}')
    if start < 0 or end < start:
        return bad
    try:
        obj=json.loads(answer[start:end+1])
    except (ValueError,TypeError):
        return bad
    if not isinstance(obj,dict) or obj.get('sentiment') not in ('positive','negative') or obj.get('topic') not in TOPICS:
        return bad
    return {'sentiment':obj['sentiment'],'topic':obj['topic'],'ok':True}
